module     Regs(input clk,
				input rst,
				input [4:0] R_addr_A, 
				input [4:0] R_addr_B, 
				input [4:0] Wt_addr, 
				input [31:0]Wt_data, 
				input L_S, 
				output [31:0] rdata_A, 
				output [31:0] rdata_B,
				input [4:0] Debug_addr,         // debug address
				output[31:0] Debug_regs        // debug data
			  );

	reg [31:0] register [1:31]; 				// r1 - r31
	integer i;

	// 实现：带写穿(write-through)的两读一写寄存器堆
	// The register file must support:
	// - Reading two registers simultaneously (rdata_A, rdata_B) with write-through
	//   (if a register is being written this cycle, reads return the new value)
	// - Writing one register per cycle when L_S is asserted (write to Wt_addr with Wt_data)
	// - x0 always reads as 0
	// - Synchronous reset clears all registers to 0
	// - Debug port reads register[Debug_addr] (0 if addr is 0)

	// 写使能：写 x0 无效
	wire wt_en = L_S & (Wt_addr != 5'b0);

	// 写口在时钟下降沿动作；读口同时做旁路，保证 WB 段正在写入的值在同一周期
	// 就能被 ID 段读到（write-through），因此 WB->ID 不需要额外的前递通路
	always @(negedge clk or posedge rst)
	begin
		if (rst) begin							// reset
			for (i = 1; i < 32; i = i + 1)
				register[i] <= 32'b0;
		end
		else if (wt_en)							// write
			register[Wt_addr] <= Wt_data;
	end

	assign rdata_A = (R_addr_A == 5'b0) ? 32'b0 :
	                 (wt_en && (Wt_addr == R_addr_A)) ? Wt_data : register[R_addr_A];	// read
	assign rdata_B = (R_addr_B == 5'b0) ? 32'b0 :
	                 (wt_en && (Wt_addr == R_addr_B)) ? Wt_data : register[R_addr_B];	// read

	assign Debug_regs = (Debug_addr == 5'b0) ? 32'b0 : register[Debug_addr];		//TEST

endmodule


===== core/RAM_B.v =====
`timescale 1ns / 1ps

module RAM_B(
    input [31:0] addra,
    input clka,      // normal clock
    input[31:0] dina,
    input wea, 
    output[31:0] douta,
    input[2:0] mem_u_b_h_w
);

    reg[7:0] data[0:127];

    initial	begin
        $readmemh("ram.mem", data);
    end

    // 实现：按字节寻址的小端写逻辑
    // Write byte/halfword/word based on mem_u_b_h_w control signals.
    // mem_u_b_h_w[1]=1 means word, mem_u_b_h_w[0]=1 means halfword, otherwise byte.
    // Only write when wea is asserted and address is within range (addra[31:7] == 0).
    always @ (negedge clka) begin
        if (wea & ~|addra[31:7]) begin
            data[addra[6:0]] <= dina[7:0];
            if (mem_u_b_h_w[0] | mem_u_b_h_w[1])
                data[addra[6:0] + 1] <= dina[15:8];
            if (mem_u_b_h_w[1]) begin
                data[addra[6:0] + 2] <= dina[23:16];
                data[addra[6:0] + 3] <= dina[31:24];
            end
        end
    end

    // 实现：按字节寻址的组合读逻辑，带符号/零扩展
    // Read byte/halfword/word based on mem_u_b_h_w.
    // mem_u_b_h_w[2]=1 means unsigned (zero-extend), otherwise sign-extend.
    // Return 0 if address is out of range.
    assign douta = addra[31:7] ? 32'b0 :
        mem_u_b_h_w[1] ? {data[addra[6:0] + 3], data[addra[6:0] + 2],
                    data[addra[6:0] + 1], data[addra[6:0]]} :
        mem_u_b_h_w[0] ? {mem_u_b_h_w[2] ? 16'b0 : {16{data[addra[6:0] + 1][7]}},
                    data[addra[6:0] + 1], data[addra[6:0]]} :
        {mem_u_b_h_w[2] ? 24'b0 : {24{data[addra[6:0]][7]}}, data[addra[6:0]]};

endmodule===== core/HazardDetectionUnit.v =====
`timescale 1ps/1ps

module HazardDetectionUnit(
    input clk,
    input Branch_ID, rs1use_ID, rs2use_ID,
    input[1:0] hazard_optype_ID,
    input[4:0] rd_EXE, rd_MEM, rs1_ID, rs2_ID, rs2_EXE,
    output PC_EN_IF, reg_FD_EN, reg_FD_stall, reg_FD_flush,
        reg_DE_EN, reg_DE_flush, reg_EM_EN, reg_EM_flush, reg_MW_EN,
    output forward_ctrl_ls,
    output[1:0] forward_ctrl_A, forward_ctrl_B
);
    // 实现：竞争检测与前递控制
    // Hints:
    // - Stall (PC_EN_IF=0, reg_FD stall, reg_DE flush) when the instruction in EX
    //   writes a register that the ID instruction reads.
    // - Branch (reg_FD_flush=1) when Branch_ID is asserted; do NOT flush reg_DE.
    // - forward_ctrl_A/B: select 2'b01 to forward from MEM stage when rd_MEM
    //   matches the ID instruction's source register.
    // - The register file has write-through for WB, so no explicit WB forwarding needed.
    // - forward_ctrl_ls: forward MEM result to store data when rd_MEM == rs2_EXE.
    // - Use hazard_optype_ID registered one cycle (to get EX stage type) for stall guard.

    localparam hazard_optype_NONE = 2'b00;   // 不写寄存器
    localparam hazard_optype_ALU  = 2'b01;   // 结果在 EX 段产生
    localparam hazard_optype_LOAD = 2'b10;   // 结果在 MEM 段产生

    // ID 段的 optype 打一拍得到 EX 段的 optype，打两拍得到 MEM 段的 optype。
    // 这是必须的：REG_ID_EX 无条件锁存 rd，所以 store/branch 会带着一个无意义
    // 的 rd 往下走，仅凭 rd_EXE / rd_MEM 判断会误报竞争。
    reg[1:0] hazard_optype_EXE = hazard_optype_NONE;
    reg[1:0] hazard_optype_MEM = hazard_optype_NONE;

    always @(posedge clk) begin
        hazard_optype_EXE <= hazard_optype_ID;
        hazard_optype_MEM <= hazard_optype_EXE;
    end

    // EX / MEM 段的指令是否真的会写一个非 x0 的寄存器
    wire EXE_write = (hazard_optype_EXE != hazard_optype_NONE) & (rd_EXE != 5'b0);
    wire MEM_write = (hazard_optype_MEM != hazard_optype_NONE) & (rd_MEM != 5'b0);

    // 前递在 ID 段完成，EX 段的结果此时还不存在 => 只能停一拍
    wire stall = EXE_write & ((rs1use_ID & (rs1_ID == rd_EXE)) |
                              (rs2use_ID & (rs2_ID == rd_EXE)));

    assign PC_EN_IF     = ~stall;       // 停顿时冻结 PC
    assign reg_FD_EN    = 1'b1;
    assign reg_FD_stall = stall;        // IF/ID 保持原值
    assign reg_FD_flush = Branch_ID;    // 跳转发生时清掉顺序取回的那条指令
    assign reg_DE_EN    = 1'b1;
    assign reg_DE_flush = stall;        // 向 EX 段注入气泡
    assign reg_EM_EN    = 1'b1;
    assign reg_EM_flush = 1'b0;
    assign reg_MW_EN    = 1'b1;

    // MEM 段结果前递到 ID 段的两个源操作数
    assign forward_ctrl_A  = (MEM_write & rs1use_ID & (rs1_ID == rd_MEM)) ? 2'b01 : 2'b00;
    assign forward_ctrl_B  = (MEM_write & rs2use_ID & (rs2_ID == rd_MEM)) ? 2'b01 : 2'b00;

    // MEM 段结果前递到 EX 段 store 指令的写数据
    assign forward_ctrl_ls = MEM_write & (rd_MEM == rs2_EXE);

endmodule

`timescale 1ns / 1ps


module  RV32core(
        input debug_en,  // debug enable
        input debug_step,  // debug step clock
        input [6:0] debug_addr,  // debug address
        output[31:0] debug_data,  // debug data
        input clk,  // main clock
        input rst,  // synchronous reset
        output[31:0] wb_pc,
        output[31:0] wb_inst,
        output[31:0] mem_addr,
        output[31:0] mem_data,
        input interrupter,  // interrupt source, for future use

        output[7:0] sim_uart_char_out,
        output sim_uart_char_valid
	);

	wire debug_clk;

	debug_clk clock(.clk(clk),.debug_en(debug_en),.debug_step(debug_step),.debug_clk(debug_clk));

    wire Branch_ctrl, JALR, RegWrite_ctrl, mem_w_ctrl, mem_r_ctrl,
        ALUSrc_A_ctrl, ALUSrc_B_ctrl, DatatoReg_ctrl, rs1use_ctrl, rs2use_ctrl,
        MRET, csr_rw_ctrl, csr_w_imm_mux_ctrl;
    wire[1:0] hazard_optype_ctrl, exp_vector_ctrl;
    wire[2:0] ImmSel_ctrl, cmp_ctrl;
    wire[3:0] ALUControl_ctrl;

    wire forward_ctrl_ls;
    wire[1:0] forward_ctrl_A, forward_ctrl_B;

	wire PC_EN_IF;
	wire [31:0] PC_IF, next_PC_IF, PC_4_IF, inst_IF, final_PC_IF;

    wire reg_FD_stall, reg_FD_flush, isFlushed_ID, cmp_res_ID;
    wire [31:0] jump_PC_ID, PC_ID, inst_ID, Debug_regs, rs1_data_reg, rs2_data_reg,
        Imm_out_ID, rs1_data_ID, rs2_data_ID, addA_ID;

