module    REG_ID_EX(input clk,                                         //ID/EX Latch
                    input rst,
                    input EN,                                          //流水寄存器使�?
                    input flush,                                       //数据竞争清除并等待：DStall
                    input [31:0] IR_ID,                                //当前译码指令(测试)
                    input [31:0] PCurrent_ID,                          //当前译码指令存储器指�?
                    input [4:0] rs1_addr,                               //当前指令读出寄存器A地址
                    input [4:0] rs2_addr,                               //当前指令读出寄存器B地址
                    input [31:0] rs1_data,                             //当前指令读出寄存器A数据
                    input [31:0] rs2_data,                             //当前指令读出寄存器A数据
                    input [31:0] Imm32,                                //当前指令读出并扩�?32位立即数�?
                    input [4:0]  rd_addr,                              //当前指令读出目的操作数地�?
                    input ALUSrc_A,                             //当前指令译码：ALU A通道控制
                    input ALUSrc_B,                             //当前指令译码：ALU B通道控制
                    input [3:0]  ALUC,                                 //当前指令译码：ALU操作控制
                    input DatatoReg,                            //当前指令译码：REG写数据�?�道选择
                    input RegWrite,                                    //当前指令译码：寄存器写信�?
                    input WR,                                          //当前指令译码：存储器读写信号
                    input [2:0] u_b_h_w,
                    input mem_r,
                    input csr_rw,
                    input csr_w_imm_mux,
                    input mret,
                    input[1:0] exp_vector,

                    output reg[31:0] PCurrent_EX,                      //锁存当前译码指令地址
                    output reg[31:0] IR_EX,                            //锁存当前译码指令(测试)
                    output reg[4:0]  rs1_EX,
                    output reg[4:0]  rs2_EX,
                    output reg[31:0] A_EX,                             //锁存当前译码指令读出寄存器A数据
                    output reg[31:0] B_EX,                             //锁存当前译码指令读出寄存器B数据
                    output reg[31:0] Imm32_EX,                          //锁存当前译码指令32位立即数�?
                    output reg[4:0]  rd_EX,                            //锁存当前译码指令写目的寄存器地址
                    output reg       ALUSrc_A_EX,                      //锁存当前译码指令ALU A通道控制
                    output reg       ALUSrc_B_EX,                      //锁存当前译码指令ALU B通道控制(保留)
                    output reg[3:0]  ALUC_EX,                          //锁存当前译码指令ALU操作功能控制
                    output reg       DatatoReg_EX,                     //锁存当前译码指令REG写数据�?�道选择
                    output reg       RegWrite_EX,                      //锁存当前译码指令寄存器写信号
                    output reg       WR_EX,                            //锁存当前译码指令存储器读写信�?
                    output reg[2:0]  u_b_h_w_EX,
                    output reg       mem_r_EX,
                    output reg       isFlushed,
                    output reg       csr_rw_EX,
                    output reg       csr_w_imm_mux_EX,
                    output reg       mret_EX,
                    output reg[1:0]  exp_vector_EX
                );

    // 实现：ID/EX 流水寄存器
    // On reset: clear rd_EX, RegWrite_EX, WR_EX, IR_EX, PCurrent_EX, rs1_EX, rs2_EX,
    //   mem_r_EX, isFlushed, csr_rw_EX, mret_EX, exp_vector_EX to 0.
    // When EN is asserted:
    //   - If flush: insert a pipeline bubble — set IR_EX to NOP (32'h00000000), clear rd_EX,
    //     RegWrite_EX, WR_EX, mem_r_EX, csr_rw_EX, mret_EX, exp_vector_EX to 0,
    //     set isFlushed to 1, but still pass PCurrent_ID to PCurrent_EX.
    //   - Else: latch all input signals to their corresponding output registers.
    always @(posedge clk) begin
        if (rst) begin
            PCurrent_EX      <= 32'b0;
            IR_EX            <= 32'b0;
            rs1_EX           <= 5'b0;
            rs2_EX           <= 5'b0;
            A_EX             <= 32'b0;
            B_EX             <= 32'b0;
            Imm32_EX         <= 32'b0;
            rd_EX            <= 5'b0;
            ALUSrc_A_EX      <= 1'b0;
            ALUSrc_B_EX      <= 1'b0;
            ALUC_EX          <= 4'b0;
            DatatoReg_EX     <= 1'b0;
            RegWrite_EX      <= 1'b0;
            WR_EX            <= 1'b0;
            u_b_h_w_EX       <= 3'b0;
            mem_r_EX         <= 1'b0;
            isFlushed        <= 1'b0;
            csr_rw_EX        <= 1'b0;
            csr_w_imm_mux_EX <= 1'b0;
            mret_EX          <= 1'b0;
            exp_vector_EX    <= 2'b0;
        end
        else if (EN) begin
            if (flush) begin                    // 插入气泡
                PCurrent_EX      <= PCurrent_ID;
                IR_EX            <= 32'h00000000;
                rs1_EX           <= 5'b0;
                rs2_EX           <= 5'b0;
                A_EX             <= 32'b0;
                B_EX             <= 32'b0;
                Imm32_EX         <= 32'b0;
                rd_EX            <= 5'b0;
                ALUSrc_A_EX      <= 1'b0;
                ALUSrc_B_EX      <= 1'b0;
                ALUC_EX          <= 4'b0;
                DatatoReg_EX     <= 1'b0;
                RegWrite_EX      <= 1'b0;
                WR_EX            <= 1'b0;
                u_b_h_w_EX       <= 3'b0;
                mem_r_EX         <= 1'b0;
                isFlushed        <= 1'b1;
                csr_rw_EX        <= 1'b0;
                csr_w_imm_mux_EX <= 1'b0;
                mret_EX          <= 1'b0;
                exp_vector_EX    <= 2'b0;
            end
            else begin
                PCurrent_EX      <= PCurrent_ID;
                IR_EX            <= IR_ID;
                rs1_EX           <= rs1_addr;
                rs2_EX           <= rs2_addr;
                A_EX             <= rs1_data;
                B_EX             <= rs2_data;
                Imm32_EX         <= Imm32;
                rd_EX            <= rd_addr;
                ALUSrc_A_EX      <= ALUSrc_A;
                ALUSrc_B_EX      <= ALUSrc_B;
                ALUC_EX          <= ALUC;
                DatatoReg_EX     <= DatatoReg;
                RegWrite_EX      <= RegWrite;
                WR_EX            <= WR;
                u_b_h_w_EX       <= u_b_h_w;
                mem_r_EX         <= mem_r;
                isFlushed        <= 1'b0;
                csr_rw_EX        <= csr_rw;
                csr_w_imm_mux_EX <= csr_w_imm_mux;
                mret_EX          <= mret;
                exp_vector_EX    <= exp_vector;
            end
        end
    end

