module   REG_EX_MEM(input clk,                                      //EX/MEM Latch
                    input rst,
                    input EN,                                       //流水寄存器使�?
                    input flush,                                    //异常时清除异常指令并等待中断处理(保留)�?
                    input [31:0] IR_EX,                             //当前执行指令(测试)
                    input [31:0] PCurrent_EX,                       //当前执行指令存储器指�?
                    input [31:0] ALUO_EX,                           //当前ALU执行输出：有效地�?或ALU操作
                    input [31:0] B_EX,                              //ID级读出寄存器B数据：CPU输出数据
                    input [4:0]  rs1_EX, rd_EX,                    //传�?�当前指令写目的寄存器地�?
                    input [31:0] rs1_data_EX,
                    input DatatoReg_EX,                      //传�?�当前指令REG写数据�?�道选择
                    input RegWrite_EX,                              //传�?�当前指令寄存器写信�?
                    input WR_EX,                                    //传�?�当前指令存储器读写信号
                    input[2:0] u_b_h_w_EX,
                    input mem_r_EX,
                    input csr_rw_EX,
                    input csr_w_imm_mux_EX,
                    input mret_EX,
                    input[1:0] exp_vector_EX,

                    output reg[31:0] PCurrent_MEM,                  //锁存传�?�当前指令地�?
                    output reg[31:0] IR_MEM,                        //锁存传�?�当前指�?(测试)
                    output reg[31:0] ALUO_MEM,                      //锁存ALU操作结果：有效地�?或ALU操作
                    output reg[31:0] Datao_MEM,                     //锁存传�?�当前指令输出mem_r数据
                    output reg[4:0]  rd_MEM,                        //锁存传�?�当前指令写目的寄存器地�?
                    output reg[4:0]  rs1_MEM,
                    output reg[31:0] rs1_data_MEM,
                    output reg       DatatoReg_MEM,                 //锁存传�?�当前指令REG写数据�?�道选择
                    output reg       RegWrite_MEM,                  //锁存传�?�当前指令寄存器写信�?
                    output reg       WR_MEM,                         //锁存传�?�当前指令存储器读写信号
                    output reg[2:0]  u_b_h_w_MEM,
                    output reg       mem_r_MEM,
                    output reg       isFlushed,
                    output reg       csr_rw_MEM,
                    output reg       csr_w_imm_mux_MEM,
                    output reg       mret_MEM,
                    output reg[1:0]  exp_vector_MEM
                );

    // 实现：EX/MEM 流水寄存器
    // On reset: clear IR_MEM, PCurrent_MEM, rd_MEM, rs1_MEM, RegWrite_MEM, WR_MEM,
    //   mem_r_MEM, isFlushed, csr_rw_MEM, mret_MEM, exp_vector_MEM to 0.
    // When EN is asserted:
    //   - If flush: clear write signals and set isFlushed, pass PCurrent_EX to PCurrent_MEM.
    //   - Else: latch all input signals to their corresponding output registers.
    always @(posedge clk) begin
        if (rst) begin
            PCurrent_MEM      <= 32'b0;
            IR_MEM            <= 32'b0;
            ALUO_MEM          <= 32'b0;
            Datao_MEM         <= 32'b0;
            rd_MEM            <= 5'b0;
            rs1_MEM           <= 5'b0;
            rs1_data_MEM      <= 32'b0;
            DatatoReg_MEM     <= 1'b0;
            RegWrite_MEM      <= 1'b0;
            WR_MEM            <= 1'b0;
            u_b_h_w_MEM       <= 3'b0;
            mem_r_MEM         <= 1'b0;
            isFlushed         <= 1'b0;
            csr_rw_MEM        <= 1'b0;
            csr_w_imm_mux_MEM <= 1'b0;
            mret_MEM          <= 1'b0;
            exp_vector_MEM    <= 2'b0;
        end
        else if (EN) begin
            if (flush) begin                    // 清除写信号
                PCurrent_MEM      <= PCurrent_EX;
                IR_MEM            <= 32'h00000000;
                ALUO_MEM          <= 32'b0;
                Datao_MEM         <= 32'b0;
                rd_MEM            <= 5'b0;
                rs1_MEM           <= 5'b0;
                rs1_data_MEM      <= 32'b0;
                DatatoReg_MEM     <= 1'b0;
                RegWrite_MEM      <= 1'b0;
                WR_MEM            <= 1'b0;
                u_b_h_w_MEM       <= 3'b0;
                mem_r_MEM         <= 1'b0;
                isFlushed         <= 1'b1;
                csr_rw_MEM        <= 1'b0;
                csr_w_imm_mux_MEM <= 1'b0;
                mret_MEM          <= 1'b0;
                exp_vector_MEM    <= 2'b0;
            end
            else begin
                PCurrent_MEM      <= PCurrent_EX;
                IR_MEM            <= IR_EX;
