module   REG_MEM_WB(input clk,                                      //MEM/WB Latch
                    input rst,
                    input EN,                                       //流水寄存器使能
                    input [31:0] IR_MEM,                             //当前执行指令(测试)
                    input [31:0] PCurrent_MEM,                       //当前执行指令存储器指针
                    input [31:0] ALUO_MEM,                           //当前ALU执行输出：有效地址或ALU操作
                    input [31:0] Datai,                              //MIOl输入CPU数据
                    input [4:0]  rd_MEM,                             //传递当前指令写目的寄存器地址
                    input DatatoReg_MEM,                      //传递当前指令REG写数据通道选择
                    input RegWrite_MEM,                              //传递当前指令寄存器写信号
                    input flush,
                    input [3:0]  exp_vector_MEM,
                    output reg[31:0] PCurrent_WB,                  //锁存传递当前指令地址
                    output reg[31:0] IR_WB,                        //锁存传递当前指令(测试)
                    output reg[31:0] ALUO_WB,                      //锁存ALU操作结果：有效地址或ALU操作
                    output reg[31:0] MDR_WB,                       //锁存MIO送CPU输入数据
                    output reg[4:0]  rd_WB,                        //锁存传递当前指令写目的寄存器地址
                    output reg       DatatoReg_WB,                 //锁存传递当前指令REG写数据通道选择
                    output reg       RegWrite_WB,                  //锁存传递当前指令寄存器写信号
                    output reg       isFlushed,
                    output reg[3:0]  exp_vector_WB
                );

    // 实现：MEM/WB 流水寄存器
    // On reset: clear rd_WB, RegWrite_WB, IR_WB, PCurrent_WB, isFlushed, exp_vector_WB to 0.
    // When EN is asserted:
    //   - If flush: clear write signals and set isFlushed, pass PCurrent_MEM to PCurrent_WB.
    //   - Else: latch all input signals to their corresponding output registers.
    always @(posedge clk) begin
        if (rst) begin
            PCurrent_WB   <= 32'b0;
            IR_WB         <= 32'b0;
            ALUO_WB       <= 32'b0;
            MDR_WB        <= 32'b0;
            rd_WB         <= 5'b0;
            DatatoReg_WB  <= 1'b0;
            RegWrite_WB   <= 1'b0;
            isFlushed     <= 1'b0;
            exp_vector_WB <= 4'b0;
        end
        else if (EN) begin
            if (flush) begin                    // 清除写信号
                PCurrent_WB   <= PCurrent_MEM;
                IR_WB         <= 32'h00000000;
                ALUO_WB       <= 32'b0;
                MDR_WB        <= 32'b0;
                rd_WB         <= 5'b0;
                DatatoReg_WB  <= 1'b0;
                RegWrite_WB   <= 1'b0;
                isFlushed     <= 1'b1;
                exp_vector_WB <= 4'b0;
            end
            else begin
                PCurrent_WB   <= PCurrent_MEM;
                IR_WB         <= IR_MEM;
                ALUO_WB       <= ALUO_MEM;
                MDR_WB        <= Datai;
                rd_WB         <= rd_MEM;
                DatatoReg_WB  <= DatatoReg_MEM;
                RegWrite_WB   <= RegWrite_MEM;
                isFlushed     <= 1'b0;
                exp_vector_WB <= exp_vector_MEM;
            end
        end
    end
endmodule
